/**
 * OpenEmrTokenProvider — exchanges a SMART backend-services
 * `client_credentials` grant against OpenEMR's `/oauth2/default/token`
 * endpoint and caches the resulting FHIR access token until it nears expiry.
 *
 * Auth model (replaces the master/password-grant flow):
 *   1. The sidecar owns an RSA-2048 keypair (generated by
 *      `agent/scripts/gen-keys.mjs`). The private key is mounted in;
 *      the public JWK is registered on `oauth_clients.jwks` by
 *      `contrib/agentforge/setup_system_client.php`.
 *   2. On each token refresh, the sidecar mints an RS384 client_assertion
 *      JWT (iss = sub = client_id, aud = token endpoint, exp = now+5m,
 *      fresh jti) and posts it as `grant_type=client_credentials`.
 *   3. OpenEMR's `JWTClientAuthenticationService::validateJWTClientAssertion`
 *      verifies the signature against the stored JWKS and issues a
 *      `system/*.read`-scoped access token.
 *
 * Why this is faster than the password grant:
 *   - No bcrypt round-trip on token refresh (the bottleneck previously).
 *   - No human-style credential to share, rotate, or audit incorrectly.
 *
 * Required env vars:
 *   OPENEMR_OAUTH_BASE_URL          URL we actually POST to. Inside docker
 *                                   this is `http://openemr/oauth2/default`.
 *   OPENEMR_FHIR_CLIENT_ID          system client id (from setup_system_client.php)
 *   OPENEMR_FHIR_PRIVATE_KEY_PATH   path to PKCS#8 PEM private key
 *     OR
 *   OPENEMR_FHIR_PRIVATE_KEY_PEM    PKCS#8 PEM contents inline (Railway-style),
 *                                   either raw multi-line PEM or base64 of it.
 *                                   Takes precedence over the file path.
 *   OPENEMR_FHIR_TLS_INSECURE       set to "1" in dev to skip cert verify
 *
 * Optional:
 *   OPENEMR_OAUTH_PUBLIC_BASE_URL   URL OpenEMR advertises in its
 *                                   discovery document (`site_addr_oath`).
 *                                   Used as the `aud` claim. Defaults to
 *                                   OPENEMR_OAUTH_BASE_URL — but inside
 *                                   docker the two differ: we POST to
 *                                   `http://openemr/...` while OpenEMR
 *                                   itself self-identifies as
 *                                   `https://localhost:9300/...`. The
 *                                   `aud` must match the latter or
 *                                   OpenEMR rejects the assertion with
 *                                   "not allowed to be used by this audience".
 */

import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { SignJWT, importPKCS8 } from 'jose';
import type { KeyLike } from 'jose';
import { Agent } from 'undici';

const FHIR_SCOPES = [
  'system/Patient.read',
  'system/Condition.read',
  'system/Observation.read',
  'system/MedicationRequest.read',
  'system/AllergyIntolerance.read',
  'system/Encounter.read',
].join(' ');

const ASSERTION_TYPE = 'urn:ietf:params:oauth:client-assertion-type:jwt-bearer';
const ASSERTION_TTL_SECONDS = 300; // 5 min — well under OpenEMR's 24h cap

interface CachedToken {
  accessToken: string;
  expiresAt: number;
}

export class OpenEmrTokenProvider {
  private cached: CachedToken | null = null;
  private privateKey: KeyLike | null = null;
  private readonly baseUrl: string;
  private readonly tokenEndpoint: string;
  private readonly audClaim: string;
  private readonly clientId: string;
  private readonly privateKeyPath: string;
  private readonly privateKeyPem: string;
  private readonly dispatcher: Agent | undefined;

  constructor(env: NodeJS.ProcessEnv = process.env) {
    this.baseUrl = (env['OPENEMR_OAUTH_BASE_URL'] ?? '').replace(/\/$/, '');
    this.tokenEndpoint = this.baseUrl ? `${this.baseUrl}/token` : '';
    const publicBase = (env['OPENEMR_OAUTH_PUBLIC_BASE_URL'] ?? '').replace(/\/$/, '');
    this.audClaim = publicBase ? `${publicBase}/token` : this.tokenEndpoint;
    this.clientId = env['OPENEMR_FHIR_CLIENT_ID'] ?? '';
    this.privateKeyPath = env['OPENEMR_FHIR_PRIVATE_KEY_PATH'] ?? '';
    this.privateKeyPem = decodePemEnv(env['OPENEMR_FHIR_PRIVATE_KEY_PEM']);
    // Per-instance dispatcher with rejectUnauthorized=false. Mutating the
    // global NODE_TLS_REJECT_UNAUTHORIZED env var would race against any
    // unrelated TLS handshake in flight (it's process-wide).
    this.dispatcher = env['OPENEMR_FHIR_TLS_INSECURE'] === '1'
      ? new Agent({ connect: { rejectUnauthorized: false } })
      : undefined;
  }

  isConfigured(): boolean {
    return Boolean(this.baseUrl && this.clientId && (this.privateKeyPem || this.privateKeyPath));
  }

  async getToken(): Promise<string> {
    if (!this.isConfigured()) {
      throw new Error(
        'OpenEMR FHIR client not configured (set OPENEMR_OAUTH_BASE_URL, OPENEMR_FHIR_CLIENT_ID, OPENEMR_FHIR_PRIVATE_KEY_PATH or OPENEMR_FHIR_PRIVATE_KEY_PEM)',
      );
    }
    const now = Date.now();
    if (this.cached && this.cached.expiresAt - 30_000 > now) {
      return this.cached.accessToken;
    }
    return this.fetchToken();
  }

  private async loadPrivateKey(): Promise<KeyLike> {
    if (this.privateKey) return this.privateKey;
    const pem = this.privateKeyPem || readFileSync(this.privateKeyPath, 'utf8');
    this.privateKey = await importPKCS8(pem, 'RS384');
    return this.privateKey;
  }

  private async mintClientAssertion(): Promise<string> {
    const key = await this.loadPrivateKey();
    const now = Math.floor(Date.now() / 1000);
    return new SignJWT({})
      .setProtectedHeader({ alg: 'RS384', kid: 'agentforge-1', typ: 'JWT' })
      .setIssuer(this.clientId)
      .setSubject(this.clientId)
      .setAudience(this.audClaim)
      .setIssuedAt(now)
      .setExpirationTime(now + ASSERTION_TTL_SECONDS)
      .setJti(randomUUID())
      .sign(key);
  }

  private async fetchToken(): Promise<string> {
    const assertion = await this.mintClientAssertion();
    const body = new URLSearchParams({
      grant_type: 'client_credentials',
      scope: FHIR_SCOPES,
      client_assertion_type: ASSERTION_TYPE,
      client_assertion: assertion,
    });

    const res = await fetch(this.tokenEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
      // dispatcher is undici-specific; node:fetch types omit it but
      // the runtime accepts it on Node 22+.
      ...(this.dispatcher ? { dispatcher: this.dispatcher } : {}),
    } as unknown as Parameters<typeof fetch>[1]);
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`OpenEMR token endpoint returned ${res.status}: ${text}`);
    }
    const json = (await res.json()) as { access_token?: string; expires_in?: number };
    if (!json.access_token) {
      throw new Error('OpenEMR token response missing access_token');
    }
    const ttl = (json.expires_in ?? 3600) * 1000;
    this.cached = {
      accessToken: json.access_token,
      expiresAt: Date.now() + ttl,
    };
    return json.access_token;
  }
}

/**
 * Accept either a raw PEM (with -----BEGIN PRIVATE KEY----- header) or a
 * base64-encoded PEM. Railway-style env vars usually arrive base64 because
 * multi-line values are awkward to set via the dashboard or CLI.
 */
function decodePemEnv(value: string | undefined): string {
  if (typeof value !== 'string' || value === '') return '';
  if (value.includes('-----BEGIN')) return value;
  try {
    return Buffer.from(value, 'base64').toString('utf8');
  } catch {
    return '';
  }
}
